cd /Users/dev/workspace/vivarium/experiments/tier3/results/workspace && python3 - <<'EOF'
import json, glob

total = 0
count = 0
for path in sorted(glob.glob('data/*.jsonl')):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            rec = json.loads(line)
            if rec.get('kind') != 'span':
                continue
            elapsed = rec.get('body', {}).get('span', {}).get('elapsed')
            if elapsed is None:
                continue
            value = elapsed['value']
            unit = elapsed['unit']
            if unit == 'ms':
                ms = value
            elif unit == 'us':
                ms = value // 1000
            elif unit == 's':
                ms = value * 1000
            else:
                raise ValueError(f"unknown unit {unit}")
            total += ms
            count += 1
print(count, total)
EOF

